INSERT INTO public.support_tickets (ticket_id, customer_id, date, subject, description, category, sentiment, resolution_status) VALUES
  ('T0001', 'C001', '2026-07-09', 'Heads up: internal restructuring', 'Wanted to flag that we''re going through a reorg this quarter, so usage from our side may look different for a while.', 'account_context', 'positive', 'resolved'),
  ('T0002', 'C004', '2026-07-14', 'Custom field values not saving', 'Values we enter into custom fields revert back after a page refresh.', 'feature', 'neutral', 'resolved'),
  ('T0003', 'C006', '2026-07-16', 'Dashboard taking 20-30 seconds to load', 'Load times have gotten noticeably worse over the past couple of weeks, especially first thing in the morning.', 'performance', 'negative', 'unresolved'),
  ('T0004', 'C011', '2026-06-15', 'Heads up: internal restructuring', 'Wanted to flag that we''re going through a reorg this quarter, so usage from our side may look different for a while.', 'account_context', 'positive', 'resolved'),
  ('T0005', 'C012', '2026-06-15', 'Approval step skipped entirely', 'One of our required approval steps is being skipped for certain record types.', 'workflow', 'neutral', 'resolved'),
  ('T0006', 'C013', '2026-05-28', 'Approval step skipped entirely', 'One of our required approval steps is being skipped for certain record types.', 'workflow', 'negative', 'unresolved'),
  ('T0007', 'C013', '2026-04-25', 'Reports timing out on large datasets', 'Any report over a few thousand rows just spins and eventually times out.', 'performance', 'negative', 'unresolved'),
  ('T0008', 'C013', '2026-04-11', 'Team members locked out after password reset', 'Two of our admins reset their passwords and are now stuck in a loop unable to log back in.', 'access', 'negative', 'unresolved'),
  ('T0009', 'C014', '2026-03-12', 'Failed payment retry not going through', 'We tried updating our card after a failed charge but the retry keeps failing too.', 'billing', 'negative', 'unresolved'),
