  ('T0013', 'C016', '2026-01-13', 'Notification rules not triggering', 'We''ve set up alerts for a couple of conditions but they never seem to fire even when the conditions are met.', 'feature', 'negative', 'escalated'),
  ('T0014', 'C017', '2026-07-14', 'Team members locked out after password reset', 'Two of our admins reset their passwords and are now stuck in a loop unable to log back in.', 'access', 'negative', 'resolved'),
  ('T0015', 'C018', '2026-08-10', 'Scheduled export stopped arriving', 'Our weekly scheduled export just stopped showing up in the destination folder a few weeks ago.', 'export', 'positive', 'resolved'),
  ('T0016', 'C020', '2026-04-07', 'Bulk update tool skipping records', 'Running a bulk update against a list of records only updates a fraction of them with no error shown.', 'feature', 'negative', 'escalated'),
  ('T0017', 'C020', '2026-05-01', 'Unable to invite a new team member', 'The invite link we sent to a new hire is coming back as expired immediately.', 'access', 'negative', 'escalated'),
